//! Python `re` patterns (`str` patterns) for the [`fancy_regex`] engine.
//!
//! `fancy-regex` is close to `re` (lookaround, backreferences), but not the same: its `\w`, `\d`,
//! `\s`, `\b` follow Unicode properties (`'₂'` is `\w` in Python only), and a few other things
//! differ at the edges. [`translate`] rewrites a Python pattern into one with the meaning
//! Python gives it:
//!
//! - `\w`, `\W`, `\d`, `\D`, `\s`, `\S`, `\b`, `\B`, inside and outside character classes, become
//!   explicit classes made from the tables of CPython (`pystr_tables.rs`, generated by
//!   `tools/gen_tables.py`, which checks them against `re` itself); with the `a` (ASCII) flag
//!   they are the ASCII classes, as in Python;
//! - the flags `a`, `u` (and the error for `L`) are handled here (the engine has no such flags);
//!   the placement rules of `re` apply: global flags only at the start of the pattern, no
//!   turning off `a`, `u`, `L`, `a` and `u` not together;
//! - `$` (without `m`) matches before a final newline too, `\Z` is the end of the text;
//! - in a character class `[`, `&` and `~` are plain characters.

use crate::pystr_tables::{DECIMAL, SPACE, WORD};

type Table = [(u32, u32)];

const ASCII_WORD: &Table = &[(0x30, 0x39), (0x41, 0x5A), (0x5F, 0x5F), (0x61, 0x7A)];
const ASCII_DECIMAL: &Table = &[(0x30, 0x39)];
const ASCII_SPACE: &Table = &[(0x9, 0xD), (0x20, 0x20)];

/// The compiled regex of `translate(pattern)?`, with the error as a message. As `re`, it has no
/// limit on backtracking (the engine's default stops a search that backtracks a million times,
/// which a long text can do).
pub fn compile(pattern: &str) -> Result<fancy_regex::Regex, String> {
    fancy_regex::RegexBuilder::new(&translate(pattern)?).backtrack_limit(usize::MAX).build().map_err(|e| e.to_string())
}

/// The flags in force at a point of the pattern.
#[derive(Clone, Copy)]
struct State {
    ascii: bool,
    ignore_case: bool,
    verbose: bool,
    multiline: bool,
}

/// A character class of the pattern: its table (Unicode or ASCII), and whether it is negated.
#[derive(Clone, Copy)]
struct Class {
    table: &'static Table,
    negated: bool,
}

fn class_of(letter: char, ascii: bool) -> Option<Class> {
    let (table, ascii_table): (&'static Table, &'static Table) = match letter.to_ascii_lowercase() {
        'w' => (WORD, ASCII_WORD),
        'd' => (DECIMAL, ASCII_DECIMAL),
        's' => (SPACE, ASCII_SPACE),
        _ => return None,
    };
    Some(Class { table: if ascii { ascii_table } else { table }, negated: letter.is_ascii_uppercase() })
}

fn push_cp(out: &mut String, cp: u32) {
    out.push_str(&format!("\\x{{{cp:X}}}"));
}

fn push_range(out: &mut String, lo: u32, hi: u32) {
    push_cp(out, lo);
    if hi > lo {
        out.push('-');
        push_cp(out, hi);
    }
}

/// The members of the class as ranges for the inside of a `[...]`; the complement does not
/// contain the surrogates (a Rust string has none).
fn push_members(out: &mut String, c: Class) {
    if !c.negated {
        for &(lo, hi) in c.table {
            push_range(out, lo, hi);
        }
        return;
    }
    let mut next = 0u32;
    let gap = |out: &mut String, lo: u32, hi: u32| {
        // [lo, hi] without the surrogates
        if lo > hi {
            return;
        }
        if lo < 0xD800 {
            push_range(out, lo, hi.min(0xD7FF));
        }
        if hi > 0xDFFF {
            push_range(out, lo.max(0xE000), hi);
        }
    };
    for &(lo, hi) in c.table {
        if lo > next {
            gap(out, next, lo - 1);
        }
        next = hi + 1;
    }
    gap(out, next, 0x10FFFF);
}

/// The class outside a `[...]`: a set of its own.
fn push_set(out: &mut String, c: Class) {
    out.push('[');
    if c.negated {
        // `[^T]` is the complement of T, with the same members as the explicit ranges
        out.push('^');
        push_members(out, Class { negated: false, ..c });
    } else {
        push_members(out, c);
    }
    out.push(']');
}

/// The set of the characters that are neither in `plain` (members of a set, as the pattern wrote
/// them) nor in any of the classes. Made as an intersection of sets, each one a plain negation:
/// the engine's negation of a set that lists a complement (`\W` as ranges) puts the surrogate
/// gap into the result (a bug of regex-syntax, in `negate`).
fn negated_set(plain: &str, cats: &[Class]) -> String {
    let mut parts: Vec<String> = Vec::new();
    let mut members = plain.to_string();
    for &cl in cats.iter().filter(|c| !c.negated) {
        push_members(&mut members, cl);
    }
    if !members.is_empty() {
        parts.push(format!("[^{members}]"));
    }
    for &cl in cats.iter().filter(|c| c.negated) {
        let mut set = String::new();
        push_set(&mut set, Class { negated: false, ..cl });
        parts.push(set);
    }
    match parts.len() {
        0 => "[\\x{0}-\\x{10FFFF}]".to_string(),
        1 => parts.remove(0),
        _ => format!("[{}]", parts.join("&&")),
    }
}

/// `\b` (or `\B`): a boundary between a `\w` and a `\W` character, the ends of the text being `\W`.
fn push_boundary(out: &mut String, ascii: bool, negated: bool) {
    let mut word = String::new();
    push_set(&mut word, class_of('w', ascii).expect("w"));
    // boundary: (?<=W)(?!W) | (?<!W)(?=W); not a boundary: (?<=W)(?=W) | (?<!W)(?!W)
    let (a, b) = if negated { ('=', '!') } else { ('!', '=') };
    out.push_str(&format!("(?:(?<={word})(?{a}{word})|(?<!{word})(?{b}{word}))"));
}

struct Parser {
    chars: Vec<char>,
    i: usize,
    out: String,
    /// the states to return to at each `)`
    stack: Vec<State>,
    state: State,
    /// only global flags so far, at the top level
    at_start: bool,
}

/// The flags of `(?flags)` or `(?on-off:`, if the group at `chars[i..]` is one: `(on, off, ends_with)`
/// and the index after the `)` or `:`.
type FlagGroup = (String, Option<String>, char, usize);

fn flag_group(chars: &[char], i: usize) -> Option<FlagGroup> {
    // chars[i..] starts with "(?"
    let mut j = i + 2;
    let mut on = String::new();
    while j < chars.len() && "aiLmsux".contains(chars[j]) {
        on.push(chars[j]);
        j += 1;
    }
    let mut off = None;
    if j < chars.len() && chars[j] == '-' {
        j += 1;
        let mut s = String::new();
        while j < chars.len() && "aiLmsux".contains(chars[j]) {
            s.push(chars[j]);
            j += 1;
        }
        off = Some(s);
    }
    match chars.get(j) {
        Some(&e) if (e == ')' || e == ':') && (!on.is_empty() || off.is_some()) => Some((on, off, e, j + 1)),
        _ => None,
    }
}

impl Parser {
    fn parse(&mut self) -> Result<(), String> {
        while self.i < self.chars.len() {
            let c = self.chars[self.i];
            match c {
                '\\' => {
                    self.at_start = false;
                    self.escape()?;
                }
                '[' => {
                    self.at_start = false;
                    self.class()?;
                }
                '(' => self.group()?,
                ')' => {
                    self.at_start = false;
                    if let Some(s) = self.stack.pop() {
                        self.state = s;
                    }
                    self.out.push(')');
                    self.i += 1;
                }
                '$' => {
                    self.at_start = false;
                    // Python: the end, or before a final newline (with `m`: before any newline)
                    self.out.push_str(if self.state.multiline { "$" } else { "(?=\\n?\\z)" });
                    self.i += 1;
                }
                '#' if self.state.verbose => {
                    // a comment up to the end of the line (kept as it is: the engine skips it too)
                    while self.i < self.chars.len() && self.chars[self.i] != '\n' {
                        self.out.push(self.chars[self.i]);
                        self.i += 1;
                    }
                }
                c if self.state.verbose && c.is_whitespace() => {
                    self.out.push(c);
                    self.i += 1;
                }
                c => {
                    self.at_start = false;
                    self.out.push(c);
                    self.i += 1;
                }
            }
        }
        Ok(())
    }

    /// `\` outside a class
    fn escape(&mut self) -> Result<(), String> {
        let Some(&e) = self.chars.get(self.i + 1) else {
            return Err("bad escape (end of pattern)".to_string());
        };
        self.i += 2;
        let mut item = String::new();
        if let Some(cl) = class_of(e, self.state.ascii) {
            push_set(&mut item, cl);
            self.push_unfolded(&item);
        } else {
            match e {
                'b' | 'B' => {
                    push_boundary(&mut item, self.state.ascii, e == 'B');
                    self.push_unfolded(&item);
                }
                'Z' => self.out.push_str("\\z"),
                e => {
                    self.out.push('\\');
                    self.out.push(e);
                }
            }
        }
        Ok(())
    }

    /// What Python matches without regard to case (`\w`, `\d`, `\s`, `\b` and their negations
    /// are not folded by `re.IGNORECASE`), made so for the engine.
    fn push_unfolded(&mut self, item: &str) {
        if self.state.ignore_case {
            self.out.push_str(&format!("(?-i:{item})"));
        } else {
            self.out.push_str(item);
        }
    }

    /// `[...]`
    fn class(&mut self) -> Result<(), String> {
        self.i += 1;
        let negated = self.chars.get(self.i) == Some(&'^');
        if negated {
            self.i += 1;
        }
        // the members that are characters and ranges (case-folded with `i`), and those that are
        // the classes `\w`... (not folded)
        let mut plain = String::new();
        let mut cats: Vec<Class> = Vec::new();
        let mut first = true;
        // the last item was a class `\w`...; the last char was a `-` that makes a range
        let (mut after_cat, mut after_dash) = (false, false);
        loop {
            let Some(&c) = self.chars.get(self.i) else {
                return Err("unterminated character set".to_string());
            };
            self.i += 1;
            let dash = c == '-' && !first && !after_cat && self.chars.get(self.i) != Some(&']');
            if after_cat && c == '-' && self.chars.get(self.i).is_some_and(|&n| n != ']') {
                return Err("bad character range".to_string());
            }
            match c {
                ']' if !first => break,
                ']' => plain.push_str("\\]"),
                '\\' => {
                    let Some(&e) = self.chars.get(self.i) else {
                        return Err("bad escape (end of pattern)".to_string());
                    };
                    self.i += 1;
                    if let Some(cl) = class_of(e, self.state.ascii) {
                        if after_dash {
                            return Err("bad character range".to_string());
                        }
                        cats.push(cl);
                        after_cat = true;
                        after_dash = false;
                        first = false;
                        continue;
                    } else if e == 'b' {
                        // backspace in a class
                        plain.push_str("\\x08");
                    } else if e == 'B' {
                        return Err("bad escape \\B".to_string());
                    } else {
                        plain.push('\\');
                        plain.push(e);
                    }
                }
                // plain characters in Python, set syntax in the engine
                '[' | '&' | '~' => {
                    plain.push('\\');
                    plain.push(c);
                }
                '^' => plain.push_str("\\^"),
                c if self.state.verbose && (c.is_whitespace() || c == '#') => push_cp(&mut plain, c as u32),
                c => plain.push(c),
            }
            after_cat = false;
            after_dash = dash;
            first = false;
        }
        let union = |out: &mut String| {
            for &cl in &cats {
                push_members(out, cl);
            }
        };
        let out = if !(self.state.ignore_case && !cats.is_empty()) {
            if !negated {
                let mut set = format!("[{plain}");
                union(&mut set);
                set + "]"
            } else if cats.iter().all(|c| !c.negated) {
                let mut set = format!("[^{plain}");
                union(&mut set);
                set + "]"
            } else {
                negated_set(&plain, &cats)
            }
        } else {
            // the classes are not folded, the characters are: two sets
            let cats_set = if negated {
                negated_set("", &cats)
            } else {
                let mut set = String::from("[");
                union(&mut set);
                set + "]"
            };
            match (negated, plain.is_empty()) {
                (false, true) => format!("(?-i:{cats_set})"),
                (false, false) => format!("(?:[{plain}]|(?-i:{cats_set}))"),
                (true, true) => format!("(?-i:{cats_set})"),
                (true, false) => format!("(?:(?![{plain}])(?-i:{cats_set}))"),
            }
        };
        self.out.push_str(&out);
        Ok(())
    }

    /// `(`: a group, or a group of flags
    fn group(&mut self) -> Result<(), String> {
        if self.chars.get(self.i + 1) == Some(&'?') {
            // a comment: (?#...)
            if self.chars.get(self.i + 2) == Some(&'#') {
                self.at_start = false;
                while self.i < self.chars.len() && self.chars[self.i] != ')' {
                    self.out.push(self.chars[self.i]);
                    self.i += 1;
                }
                return Ok(());
            }
            if let Some((on, off, end, next)) = flag_group(&self.chars, self.i) {
                return self.flags(&on, off.as_deref(), end, next);
            }
        }
        self.at_start = false;
        self.stack.push(self.state);
        self.out.push('(');
        self.i += 1;
        Ok(())
    }

    fn flags(&mut self, on: &str, off: Option<&str>, end: char, next: usize) -> Result<(), String> {
        if on.contains('L') {
            return Err("bad inline flags: cannot use 'L' flag with a str pattern".to_string());
        }
        if on.contains('a') && on.contains('u') {
            return Err("bad inline flags: flags 'a', 'u' and 'L' are incompatible".to_string());
        }
        if let Some(off) = off {
            if off.is_empty() {
                return Err("missing flag".to_string());
            }
            if off.contains(['a', 'u', 'L']) {
                return Err("bad inline flags: cannot turn off flags 'a', 'u' and 'L'".to_string());
            }
        }
        let global = end == ')';
        if global {
            if off.is_some() {
                return Err("missing :".to_string());
            }
            if !self.at_start {
                return Err("global flags not at the start of the expression".to_string());
            }
        } else {
            self.at_start = false;
        }
        // the new state, in the group (or from here, for global flags)
        let mut st = self.state;
        if on.contains('a') {
            st.ascii = true;
        }
        if on.contains('u') {
            st.ascii = false;
        }
        for (flags, value) in [(on, true), (off.unwrap_or(""), false)] {
            if flags.contains('x') {
                st.verbose = value;
            }
            if flags.contains('m') {
                st.multiline = value;
            }
            if flags.contains('i') {
                st.ignore_case = value;
            }
        }
        // the flags the engine knows
        let keep = |s: &str| s.chars().filter(|c| !"auL".contains(*c)).collect::<String>();
        let (on_k, off_k) = (keep(on), off.map(keep).unwrap_or_default());
        let spec = if off_k.is_empty() { on_k } else { format!("{on_k}-{off_k}") };
        if global {
            if !spec.is_empty() {
                self.out.push_str(&format!("(?{spec})"));
            }
        } else {
            self.stack.push(self.state);
            self.out.push_str(&format!("(?{spec}:"));
        }
        self.state = st;
        self.i = next;
        Ok(())
    }
}

/// Rewrite a Python `re` pattern (`str`, default flags) into a [`fancy_regex`] pattern with the
/// same meaning. Errors are those of `re.compile` for the cases that are checked here (flags);
/// the rest is left to the engine.
pub fn translate(pattern: &str) -> Result<String, String> {
    let mut p = Parser {
        chars: pattern.chars().collect(),
        i: 0,
        out: String::with_capacity(pattern.len()),
        stack: Vec::new(),
        state: State { ascii: false, ignore_case: false, verbose: false, multiline: false },
        at_start: true,
    };
    p.parse()?;
    Ok(p.out)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn matches(pattern: &str, text: &str) -> bool {
        compile(pattern).unwrap().is_match(text).unwrap()
    }

    #[test]
    fn classes_as_in_python() {
        assert!(matches(r"^\w$", "\u{2082}")); // '₂' is \w in Python
        assert!(!matches(r"^\w$", "\u{200d}"));
        assert!(matches(r"^[\w]$", "_"));
        assert!(matches(r"^[^\W\d]+$", "ab_c"));
        assert!(!matches(r"^[^\W\d]+$", "ab1"));
        assert!(matches(r"^\d$", "\u{664}"));
        assert!(!matches(r"^\d$", "\u{b2}"));
        assert!(matches(r"^\s$", "\u{1c}"));
        assert!(matches(r"a\b", "a b"));
        assert!(!matches(r"a\b", "a\u{2082}"));
        assert!(matches(r"a\B", "a\u{2082}"));
        assert!(matches(r"\B", ""));
        assert!(!matches(r"\b", ""));
        assert!(matches(r"[\b]", "\u{8}"));
    }

    #[test]
    fn ascii_flag() {
        assert!(!matches(r"(?a)^\w$", "\u{e9}"));
        assert!(matches(r"(?a)^\W$", "\u{e9}"));
        assert!(!matches(r"(?a)^\s$", "\u{1c}"));
        assert!(matches(r"(?a)^\s$", "\u{b}"));
        assert!(matches(r"^(?a:\w)(?u:\w)$", "a\u{e9}"));
        assert!(!matches(r"^(?a:\w)(?u:\w)$", "\u{e9}a"));
    }

    #[test]
    fn flag_errors() {
        assert!(translate(r"x(?i)y").is_err());
        assert!(translate(r"(?L)x").is_err());
        assert!(translate(r"(?au)x").is_err());
        assert!(translate(r"(?-a:x)").is_err());
        assert!(translate(r"(?-i)x").is_err());
        assert!(translate(r"(?i)(?s)x").is_ok());
    }

    #[test]
    fn dollar_and_z() {
        assert!(matches(r"a$", "a\n"));
        assert!(!matches(r"a\Z", "a\n"));
        assert!(!matches(r"a$", "a\n\n"));
        assert!(matches(r"(?m)a$", "a\nb"));
    }

    #[test]
    fn verbose_and_bad_ranges() {
        // (?x): whitespace and comments are ignored, but not in a set
        assert!(matches(r"(?x)^ a [ b] # c ( d", "ab"));
        assert!(matches(r"(?x)^[ #]+$", " #"));
        assert!(translate(r"[\w-a]").is_err());
        assert!(translate(r"[a-\w]").is_err());
        assert!(translate(r"[\B]").is_err());
        assert!(translate(r"[\w-]").is_ok() && translate(r"[-\w]").is_ok());
    }

    #[test]
    fn ignore_case_does_not_fold_the_classes() {
        // U+0345 folds to U+03B9 (a letter) but is not itself \w in Python
        assert!(!matches(r"(?i)^\w$", "\u{345}"));
        assert!(!matches(r"(?i)^[\w]$", "\u{345}"));
        assert!(matches(r"(?i)^[\Wa]$", "\u{345}"));
        assert!(matches(r"(?i)^[\Wa]$", "A"));
        assert!(!matches(r"(?i)^[^a\w]$", "A"));
        assert!(matches(r"(?i)^[^a\W]$", "_"));
    }

    #[test]
    fn set_syntax_is_plain() {
        assert!(matches(r"^[[]$", "["));
        assert!(matches(r"^[a&&b]+$", "&ab"));
        assert!(matches(r"^[]a]+$", "]a"));
    }
}
